cat > game.js <<'EOF'
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const scoreEl=document.getElementById('score'),multiEl=document.getElementById('multi'),distanceEl=document.getElementById('distance');
const start=document.getElementById('start'),gameover=document.getElementById('gameover'),hud=document.getElementById('hud'),boostUI=document.getElementById('boost'),boostBar=document.getElementById('boostBar');
let W,H,dpr,state='menu',last=0,time=0,score=0,distance=0,multi=1,shake=0;
let player,obstacles=[],particles=[],stars=[],keys={},boost=100;
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);stars=Array.from({length:90},()=>({x:Math.random()*W,y:Math.random()*H,s:Math.random()*1.5+.2,a:Math.random()}))}
addEventListener('resize',resize);resize();
function reset(){player={x:W*.5,y:H*.72,r:13,tx:W*.5,ty:H*.72,trail:[]};obstacles=[];particles=[];score=0;distance=0;multi=1;boost=100;time=0;last=performance.now();state='play';start.classList.remove('visible');gameover.classList.remove('visible');hud.classList.add('on');boostUI.classList.add('on')}
function spawn(){const lane=Math.random()<.55?'x':'y';if(lane==='x'){let w=35+Math.random()*55,h=28+Math.random()*28,x=-w-Math.random()*100*(Math.random()<.5?1:-1);if(Math.random()<.5)x=W+Math.random()*100;obstacles.push({x,y:80+Math.random()*(H-180),w,h,vx:(x<0?1:-1)*(170+Math.random()*130),vy:(Math.random()-.5)*50,kind:Math.random()<.25?'gate':'block',rot:0})}else{obstacles.push({x:30+Math.random()*(W-60),y:-50,w:25+Math.random()*45,h:35+Math.random()*55,vx:(Math.random()-.5)*60,vy:210+Math.random()*150,kind:Math.random()<.25?'gate':'block'})}}
function burst(x,y,color,n=12){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=Math.random()*180+40;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,l:1,size:Math.random()*3+1,color})}}
function update(dt){time+=dt;distance+=dt*(.014*(1+time*.018));let speed=260+Math.min(time*9,300);if(keys.ArrowLeft||keys.a)player.tx-=speed*dt;if(keys.ArrowRight||keys.d)player.tx+=speed*dt;if(keys.ArrowUp||keys.w)player.ty-=speed*dt;if(keys.ArrowDown||keys.s)player.ty+=speed*dt;let boosting=(keys[' ']||keys.Space)&&boost>3;if(boosting){boost-=28*dt;speed+=180}else boost=Math.min(100,boost+10*dt);player.tx=Math.max(24,Math.min(W-24,player.tx));player.ty=Math.max(95,Math.min(H-24,player.ty));player.x+=(player.tx-player.x)*Math.min(1,dt*12);player.y+=(player.ty-player.y)*Math.min(1,dt*12);player.trail.unshift({x:player.x,y:player.y,a:1});if(player.trail.length>14)player.trail.pop();if(boosting&&Math.random()<.8)particles.push({x:player.x+(Math.random()-2)*8,y:player.y+12,vx:(Math.random()-.5)*30,vy:160+Math.random()*100,l:1,size:2,color:'#6ef7ff'});
  let spawnRate=Math.max(.28,.9-time*.012);if(!update.next||time>update.next){spawn();update.next=time+spawnRate*(.65+Math.random()*1)}obstacles.forEach(o=>{o.x+=o.vx*dt;o.y+=o.vy*dt;o.rot+=dt*o.vx*.003});obstacles=obstacles.filter(o=>o.x>-100&&o.x<W+100&&o.y>-100&&o.y<H+100);
  for(let o of obstacles){let dx=Math.abs(player.x-o.x),dy=Math.abs(player.y-o.y);if(dx<(o.w/2+player.r*.7)&&dy<(o.h/2+player.r*.7)){burst(player.x,player.y,'#ff3ba7',30);state='over';shake=18;hud.classList.remove('on');boostUI.classList.remove('on');document.getElementById('finalScore').textContent=Math.floor(score).toLocaleString();let best=Math.max(Number(localStorage.getItem('neonBest')||0),Math.floor(score));localStorage.setItem('neonBest',best);document.getElementById('bestScore').textContent=best.toLocaleString();setTimeout(()=>gameover.classList.add('visible'),450);break}}
  particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=180*dt;p.l-=dt*1.7});particles=particles.filter(p=>p.l>0);multi=Math.min(8,1+Math.floor(distance/180));score+=dt*(100+time*3)*multi;boostBar.style.width=boost+'%';scoreEl.textContent=Math.floor(score).toString().padStart(6,'0');multiEl.textContent='×'+multi;distanceEl.textContent=Math.floor(distance*100)+'m'}
function draw(){ctx.save();if(shake>0){ctx.translate((Math.random()-1)*shake,(Math.random()-1)*shake);shake*=.88;if(shake<.3)shake=0}ctx.fillStyle='#080711';ctx.fillRect(-30,-30,W+60,H+60);
  ctx.strokeStyle='rgba(110,247,255,.07)';ctx.lineWidth=1;let horizon=H*.34,offset=(time*90)%44;for(let i=-W;i<W*2;i+=44){ctx.beginPath();ctx.moveTo(W/2+(i-W/2)*.1,horizon);ctx.lineTo(W/2+(i-W/2)*1.5,H);ctx.stroke()}for(let y=horizon;y<H;y+=44){let p=(y-horizon)/(H-horizon),yy=horizon+(p*p*(H-horizon)+offset*.25*p)%((H-horizon)+44);ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(W,yy);ctx.stroke()}stars.forEach(s=>{ctx.globalAlpha=.25+s.a*.5;ctx.fillStyle='#8caad0';ctx.fillRect(s.x,(s.y+time*12*s.s)%H,s.s,s.s)});ctx.globalAlpha=1;
  ctx.save();ctx.translate(player.x,player.y);ctx.shadowBlur=18;ctx.shadowColor='#6ef7ff';ctx.fillStyle='#dffeff';ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(12,12);ctx.lineTo(0,8);ctx.lineTo(-12,12);ctx.closePath();ctx.fill();ctx.strokeStyle='#6ef7ff';ctx.lineWidth=2;ctx.stroke();ctx.restore();player.trail.forEach((t,i)=>{ctx.globalAlpha=(1-i/player.trail.length)*.18;ctx.fillStyle='#6ef7ff';ctx.beginPath();ctx.arc(t.x,t.y,5*(1-i/player.trail.length)+1,0,7);ctx.fill()});ctx.globalAlpha=1;
  obstacles.forEach(o=>{ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.rot);ctx.shadowBlur=12;ctx.shadowColor=o.kind==='gate'?'#ff3ba7':'#c66cff';ctx.fillStyle=o.kind==='gate'?'rgba(255,59,167,.18)':'rgba(156,74,210,.16)';ctx.strokeStyle=o.kind==='gate'?'#ff3ba7':'#c66cff';ctx.lineWidth=2;ctx.beginPath();ctx.rect(-o.w/2,-o.h/2,o.w,o.h);ctx.fill();ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.fillRect(-o.w/2+5,-o.h/2+5,o.w-10,2);ctx.restore()});particles.forEach(p=>{ctx.globalAlpha=Math.max(0,p.l);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)});ctx.globalAlpha=1;ctx.restore()}
function loop(now){let dt=Math.min(.032,(now-last)/1000||0);last=now;if(state==='play')update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
function key(e,on){const k=e.key.length===1?e.key.toLowerCase():e.key;keys[k]=on;if(on&&(k===' '||k==='Space'))keys[' ']=true;if(!on&&(k===' '||k==='Space'))keys[' ']=false;e.preventDefault()}addEventListener('keydown',e=>key(e,true));addEventListener('keyup',e=>key(e,false));
document.getElementById('play').onclick=()=>reset();document.getElementById('again').onclick=()=>reset();
document.querySelectorAll('#controls button').forEach(b=>{const map={left:'ArrowLeft',right:'ArrowRight',up:'ArrowUp',down:'ArrowDown'};let el=map[b.dataset.key];const on=e=>{e.prevent;keys[el]=true};b.addEventListener('pointerdown',e=>{e.preventDefault();keys[el]=true;b.setPointerCapture(e.pointerId)});b.addEventListener('pointerup',()=>keys[el]=false);b.addEventListener('pointercancel',()=>keys[el]=false)});
let pointer={active:false};canvas.addEventListener('pointerdown',e=>{if(state==='play'){pointer.active=true;player.tx=e.clientX;player.ty=e.clientY}});canvas.addEventListener('pointermove',e=>{if(pointer.active){player.tx=e.clientX;player.ty=e.clientY}});addEventListener('pointerup',()=>pointer.active=false);
EOF
